import React from 'react'
import styled, { keyframes } from 'styled-components'
import { device } from '../../helpers/MediaQ'
import { Main_ } from '../button/Main_'
import { Main_Plain } from '../button/Main_Plain'
import { Grey_Link } from '../button/Grey_Link'

const SlideIn = keyframes`
 0%{
    top: -100%;
 }
 100%{
    top: 5rem;
 }
`

const Confirmation = styled.div`
    position: ${p => p.storybook ? 'static' : 'fixed'};
    top: 0;
    left: 0;
    z-index: 5000;
    width: 100%;
    min-height: 100vh;
    background: ${p => p.theme.overlay};
`

const ConfirmationTop = styled.div`
    display: flex;
    align-items: center;
    justify-content: flex-end;
    margin-bottom: 1rem;
`

const ConfirmationBackground = styled.div`
    position: ${p => p.storybook ? 'static' : 'fixed'};
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    z-index: 4999;
`

const ConfirmationContainer = styled.div`
    position: ${p => p.storybook ? 'static' : 'fixed'};
    top: 5rem;
    left: 50%;
    width: calc(100vw - 4rem);
    max-width: 50rem;
    transform: translateX(-50%);
    z-index: 5001;
    padding: var(--normalPads);
    border-radius: var(--smallRadius);
    background: ${p => p.theme.background};
    text-align: center;
    animation: ${SlideIn} .5s linear;
`

const ConfirmationActions = styled.div`
    margin-top: 2rem;
    padding: 1rem 0;
    display: flex;
    align-items: center;
    justify-content: space-between;

    @media ${device.sm}{
        
        button{

            span{
                display: none;
            }
        }
    }
`

export const Confirmation_ = (props) => {
    return (
      <Confirmation storybook={props.storybook} className={props.className + ' ' + 'Confirmation'} >
          <ConfirmationBackground onClick={props.onClose}></ConfirmationBackground>
          <ConfirmationContainer storybook={props.storybook}>
            {props.onClose ?
                <ConfirmationTop>
                    <Grey_Link noPadding size="small" iconLeft="Xicon" onClick={props.onClose}/>
                </ConfirmationTop>
            :
                null
            }
              <h4>{props.message}</h4>
              <ConfirmationActions>
                  <Main_Plain 
                    id={props.idYes}
                    onClick = {props.onYes}
                    iconLeft = 'Check'
                    text = {props.yes}
                  />
                  <Main_ 
                    id={props.idNo}
                    onClick = {props.onNo}
                    iconLeft = 'Xicon'
                    text = {props.no}
                  />
              </ConfirmationActions>
          </ConfirmationContainer>
      </Confirmation>
    )
  }
