import React from "react";
import Calendar from "react-calendar";
import styled from "styled-components";
import "react-calendar/dist/Calendar.css";
// import { formatDate } from "react-calendar/dist/cjs/shared/dateFormatter";

const Dates = styled.div`
   abbr{
        font-size: 1.2rem !important;
        font-family: 'fontBold';
    }

  .react-calendar {
    width: 100%;
    font-family: "fontMedium", sans-serif;
    background: ${(p) => p.theme.background};
    color: ${(p) => p.theme.color};
    box-shadow: ${(p) => p.theme.in};
    border-radius: var(--smallRadius);
    overflow: hidden;
    border: none;
  }

  .react-calendar__tile:disabled {
    background: ${(p) => p.theme.low} !important;
    opacity: .5 !important;
    cursor: not-allowed !important;
  }
  .react-calendar__tile {
    color: ${(p) => p.theme.color};
  }

  .react-calendar__tile:enabled:hover {
    background: ${(p) => p.theme.low};
  }

  .react-calendar__month-view__days__day--weekend {
    color: var(--error);
  }

  .react-calendar__tile--now {
    background: ${(p) => p.theme.low};
  }

  .react-calendar__tile--active {
    background: var(--mainLight);
    color: white;
  }

  .react-calendar__tile--active:enabled:hover,
  .react-calendar__tile--active:enabled:focus {
    background: var(--main);
  }

  .react-calendar__navigation button:enabled:hover,
  .react-calendar__navigation button:enabled:focus {
    background: ${(p) => p.theme.low};
  }

  .react-calendar__navigation__label__labelText {
    color: ${(p) => p.theme.color};
  }

  .react-calendar__navigation button:disabled {
    background: ${(p) => p.theme.background};
    box-shadow: ${(p) => p.theme.in};
  }

  .react-calendar__navigation button {
    color: ${(p) => p.theme.color};
  }

  .react-calendar--selectRange .react-calendar__tile--hover {
    background: ${(p) => p.theme.low};
  }
`;

export const Dates_ = (p) => {
  return (
    <Dates>
      <Calendar
        view={p.view}
        onChange={p.onChange}
        value={p.value}
        selectRange={p.selectRange}
        dateFullCellRender={p.dateFullCellRender}
        maxDate={p.maxDate}
        minDate={p.minDate}
        allowPartialRange={p.allowPartialRange}
        defaultActiveStartDate={p.defaultActiveStartDate}
        maxDetail={p.maxDetail}
        minDetail={p.minDetail}
        // formatLongDate={(locale, date) => formatDate(date, "dd MMM YYYY")}
      />
    </Dates>
  );
};
