import React from "react";
import styled from "styled-components";
import { IconSvg } from "../../svg/IconSvg";
import { Button } from "../../helpers/Button";

const DeletePlain = styled(Button)`
  background: transparent;
  border: 1px solid transparent;

  span {
    color: var(--error) !important;
  }

  svg {
    fill: var(--error) !important;
  }

  &:hover {
    span {
      color: var(--errorLight) !important;
    }

    svg {
      fill: var(--errorLight) !important;
    }
  }
`;

export const Delete_Plain = (props) => {
  return (
    <DeletePlain
      className={props.className + " " + "DeletePlain"}
      id={props.id}
      noPadding={props.noPadding}
      size={props.size}
      onClick={props.onClick}
    >
      {props.iconLeft ? (
        <IconSvg Icon={props.iconLeft} />
      ) : props.localIconLeft ? (
        <>{props.localIconLeft}</>
      ) : null}
      {props.text ? <span>{props.text}</span> : null}
      {props.iconRight ? (
        <IconSvg Icon={props.iconRight} />
      ) : props.localIconRight ? (
        <>{props.localIconRight}</>
      ) : null}
    </DeletePlain>
  );
};
