import React, { useState } from "react";
import styled from "styled-components";
import { breakPoints } from "../../helpers/MediaQ";
import { CardsFull } from "../../styles/Cards";
import { Stat_Loader } from "./Stat_Loader";

const FullStatLoader = styled(CardsFull)``;

export const Full_Stat_Loader = (props) => {
  const getInitialRepeats = () => {
    const width = window.innerWidth;
    if (width > breakPoints.lg) {
      return 10;
    } else if (width <= breakPoints.lg && width > breakPoints.md) {
      return 6;
    } else if (width <= breakPoints.md && width > breakPoints.sm) {
      return 4;
    } else {
      return 2;
    }
  };

  const [repeats, setRepeats] = useState(getInitialRepeats());

  const ChangeRepeats = (width) => {
    if (width > breakPoints.lg) {
      setRepeats(10);
    } else if (width <= breakPoints.lg && width > breakPoints.md) {
      setRepeats(6);
    } else if (width <= breakPoints.md && width > breakPoints.sm) {
      setRepeats(4);
    } else if (width <= breakPoints.sm) {
      setRepeats(2);
    }
  };

  window.addEventListener("resize", () => {
    let width = window.innerWidth;
    ChangeRepeats(width);
  });

  window.addEventListener("load", () => {
    let width = window.innerWidth;
    ChangeRepeats(width);
  });

  return (
    <FullStatLoader>
      {[...Array(repeats)].map((i) => (
        <Stat_Loader key={i} children={props.children} circle={props.circle} />
      ))}
    </FullStatLoader>
  );
};
