import React from 'react'
import {Main_} from "../button/Main_"
import {Grey_} from "../button/Grey_"
import styled from 'styled-components'
import { IconSvg } from '../../svg/IconSvg'
import { device } from '../../helpers/MediaQ'
import { Grey_Link } from '../button'


const Notification = styled.li`
  padding: 1rem;
  border-radius: var(--smallRadius);
  border: 2px solid ${p => p.sentiment==="negative" ? "var(--error)" :p.sentiment==="positive" ? "var(--success)" :p.sentiment === "neutral" ? "var(--warning)" : "var(--greyDark)"};
  position: relative;
`

const NotificationBoxBg = styled.div`
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  width: 100%;
  background: ${p => p.sentiment==="negative" ? "var(--error)" :p.sentiment==="positive" ? "var(--success)" :p.sentiment === "neutral" ? "var(--warning)" : "var(--greyDark)"};
  opacity: .1;
`

const NotificationBoxWrapper = styled.div`
  display: grid;
  grid-template-columns: auto 1fr;
  grid-gap: 1rem;
  opacity: ${p => p.read ? ".5" : "1"};
`

const NotificationBoxAvatar = styled.div`
  aspect-ratio: 1/1;
  height: 7rem;
  border-radius: var(--smallRadius);
  overflow: hidden;

  img{
    width: 100%;
    height: 100%;
    object-fit: cover;
  }
`

const NotificationBoxInfo = styled.div``

const NotificationBoxPage = styled.div``

const NotificationBoxTitle = styled.div`
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  margin-top: 1rem;
  opacity: ${p => p.read ? ".5" : "1"};

  h4{
    line-height: 1;
  }

  h6{
    line-height: 1;
    font-size: 1.2rem;
    margin-bottom: .5rem;
  }
`

const NotificationBoxIcon = styled.div`
  padding: .2rem .5rem;
  border-radius: var(--smallRadius);
  border: 2px solid ${p => p.sentiment==="negative" ? "var(--error)" :p.sentiment==="positive" ? "var(--success)" :p.sentiment === "neutral" ? "var(--warning)" : "var(--greyDark)"};

  svg{
    width: 2.5rem;
    fill: ${p => p.sentiment==="negative" ? "var(--error)" :p.sentiment==="positive" ? "var(--success)" :p.sentiment === "neutral" ? "var(--warning)" : "var(--greyDark)"};
  }
`

const NotificationBoxActions = styled.div`
  display: flex;
  align-items: center;
  gap: 1rem;
  position: relative;
  margin-top: 1rem;

  @media ${device.xs} {
    flex-direction: column;
    align-items: flex-start;
    gap: .5rem;
    width: 100%;
    
    button{
      width: 100%;
      justify-content: center;
    }
  }
`

const NotificationBoxBottom = styled.div`
  display: flex;
  align-items: flex-end;
  gap: 1rem;
  justify-content: space-between;
  margin-top: 1rem;

  h6{
    width: 100%;
    text-align: right;
  }

  @media ${device.xs} {
    flex-direction: column;
    align-items: flex-start;
    gap: .5rem;
  }
`

export const Notification_ = (props) => {
  return (
    <Notification sentiment={props.sentiment}>
        <NotificationBoxBg sentiment={props.sentiment}></NotificationBoxBg>
        <NotificationBoxWrapper read={props.read}>
          <NotificationBoxAvatar>
              <img src={props.asset} />
          </NotificationBoxAvatar>
          <NotificationBoxInfo>
              <NotificationBoxPage>
              <h5>{props.business}</h5>
              <h6>{props.tool}</h6>
              <p>{props.name}</p>
              </NotificationBoxPage>
          </NotificationBoxInfo>
        </NotificationBoxWrapper>
        <NotificationBoxTitle read={props.read} sentiment={props.sentiment}>
            <NotificationBoxIcon sentiment={props.sentiment}>
                <IconSvg Icon={props.type} />
            </NotificationBoxIcon>
            <div>
              <h6>{props.info}</h6>
              <h4>{props.message}</h4>
            </div>
        </NotificationBoxTitle>
        <NotificationBoxBottom>
          <NotificationBoxActions>
              {props.action ?
                  <Main_ text={props.action} size="small" onClick={props.onAction}/>
              :
                  null
              }
              {props.dismiss ?
                <Grey_Link text={props.dismiss} size="small" onClick={props.onDismiss}/>
              :
                null
              }
          </NotificationBoxActions>
          <h6 className='Date'>{props.date}</h6>
        </NotificationBoxBottom>
        
    </Notification>
  )
}
