import React, { useEffect, useState } from "react";
import styled from "styled-components";
import { breakPoints } from "../../helpers/MediaQ";
import { CardsSixty } from "../../styles/Cards";
import { Stat_Loader } from "./Stat_Loader";

const SixtyStatLoader = styled(CardsSixty)``;

export const Sixty_Stat_Loader = (props) => {
  const [repeats, setRepeats] = useState();
  const ChangeRepeats = (width) => {
    if (width > breakPoints.xl) {
      setRepeats(6);
    } else if (width <= breakPoints.xl && width > breakPoints.md) {
      setRepeats(4);
    } else if (width <= breakPoints.md && width > breakPoints.sm) {
      setRepeats(6);
    } else if (width <= breakPoints.sm && width > breakPoints.xs) {
      setRepeats(4);
    } else if (width < breakPoints.xs) {
      setRepeats(2);
    }
  };

  window.addEventListener("resize", () => {
    let width = window.innerWidth;
    ChangeRepeats(width);
  });

  useEffect(() => {
    let width = window.innerWidth;
    ChangeRepeats(width);
  }, []);

  return (
    <SixtyStatLoader>
      {[...Array(repeats)]?.map((i) => (
        <Stat_Loader key={i} children={props.children} circle={props.circle} />
      ))}
    </SixtyStatLoader>
  );
};
