import React from "react";
import styled from "styled-components";
import { Main_, Main_Plain, Red_ } from "../button";
import Upload_ from "./Upload_";
import { device } from "../../helpers/MediaQ";
import {
  ValidatorError,
  ValidatorSuccess,
  ValidatorTip,
  ValidatorWarning,
  Validators,
} from "../../helpers/Validator";
import { IconSvg } from "../../svg/IconSvg";

const UploadAvatar = styled.div`
  background: ${(p) => p.theme.low};
  padding: var(--largePads);
  border-radius: var(--normalRadius);

  h4 {
    margin-bottom: 2rem;
  }
`;

const UploadAvatarGrid = styled.div`
  display: grid;
  grid-template-columns: 1fr 3fr;
  grid-gap: 2rem;

  @media ${device.xs} {
    grid-template-columns: 1fr;
  }
`;

const UploadAvatarImage = styled.div`
  width: 100%;
  aspect-ratio: 1/1;
  background: ${(p) => p.theme.bg};
  border-radius: 2rem;
  overflow: hidden;

  img {
    height: 100%;
    width: 100%;
    object-fit: cover;
  }
`;

const UploadAvatarActions = styled.div``;

export const Upload_Avatar = (props) => {
  return (
    <UploadAvatar>
      <h4>{props.title}</h4>
      <UploadAvatarGrid>
        <UploadAvatarImage>
          {props.img ? (
            <img src={props.img} />
          ) : (
            <img
              src={
                props.imgDefault
                  ? props.imgDefault
                  : "https://genius1071.friktoriaservers.net/doitforme/morning/app/boiler/DefaultAvatar.jpg"
              }
            />
          )}
        </UploadAvatarImage>
        <UploadAvatarActions>
          <Upload_
            maxFiles="1"
            getFilesFromChild={props.getFilesFromChild}
            boomRejected={props.boomRejected}
            accept={props.accept}
            onClick={props.onUpload}
            text={props.upload}
            iconLeft={props.iconUpload ? props.iconUpload : "Upload"}
            maxSize={props.maxSize}
            userId={props.userId}
          />
          {props.uploaded ? (
            <Red_
              onClick={props.onDelete}
              text={props.delete}
              iconLeft={props.iconUpload ? props.iconUpload : "Delete"}
            />
          ) : null}
          {props.errors ? (
            <Validators className="ValidatorErrors">
              {props.errors?.map((error, i) => (
                <ValidatorError key={i}>
                  <IconSvg Icon="Error" />
                  <h6>{error}</h6>
                </ValidatorError>
              ))}
            </Validators>
          ) : null}
          {props.successes ? (
            <Validators className="ValidatorSuccesses">
              {props.successes?.map((success, i) => (
                <ValidatorSuccess key={i}>
                  <IconSvg Icon="Check" />
                  <h6>{success}</h6>
                </ValidatorSuccess>
              ))}
            </Validators>
          ) : null}
          {props.helpers ? (
            <Validators className="ValidatorHelpers">
              {props.helpers?.map((helper, i) => (
                <ValidatorWarning key={i}>
                  <IconSvg Icon="Warning" />
                  <h6>{helper}</h6>
                </ValidatorWarning>
              ))}
            </Validators>
          ) : null}
          {props.tips ? (
            <Validators className="ValidatorTips">
              {props.tips?.map((tip, i) => (
                <ValidatorTip key={i}>
                  <IconSvg Icon="Tip" />
                  <h6>{tip}</h6>
                </ValidatorTip>
              ))}
            </Validators>
          ) : null}
        </UploadAvatarActions>
      </UploadAvatarGrid>
    </UploadAvatar>
  );
};
