import React from "react";
import styled from "styled-components";
import { IconSvg } from "../../svg/IconSvg";
import { Button } from "../../helpers/Button";

const DarkPlain = styled(Button)`
  background: transparent;
  border: 1px solid transparent;
  border-bottom: ${(p) =>
    p.active ? "1px solid var(--mainDark)" : "1px solid transparent"};

  span {
    color: var(--mainDark) !important;
  }

  svg {
    fill: var(--mainDark) !important;
  }

  &:hover {
    span {
      color: var(--main) !important;
    }

    svg {
      fill: var(--main) !important;
    }
  }
`;

export const Dark_Plain = (props) => {
  return (
    <DarkPlain
      className={props.className + " " + "DarkPlain"}
      id={props.id}
      noPadding={props.noPadding}
      size={props.size}
      onClick={props.onClick}
      active={props.active}
    >
      {props.iconLeft ? (
        <IconSvg Icon={props.iconLeft} />
      ) : props.localIconLeft ? (
        <>{props.localIconLeft}</>
      ) : null}
      {props.text ? <span>{props.text}</span> : null}
      {props.iconRight ? (
        <IconSvg Icon={props.iconRight} />
      ) : props.localIconRight ? (
        <>{props.localIconRight}</>
      ) : null}
    </DarkPlain>
  );
};
