import React from "react";
import styled, { keyframes } from "styled-components";
import { Card } from "../../helpers/Card";
import { IconSvg } from "../../svg/IconSvg";
import { Focus_ } from "../button/Focus_";

const boxShadowAnimation = keyframes`
  0% {
    box-shadow: -3px -3px 10px var(--focus);
  }
  25% {
    box-shadow: 3px -3px 10px var(--focus);
  }
  50% {
    box-shadow: 3px 3px 10px var(--focus);
  }
  75% {
    box-shadow: -3px 3px 10px var(--focus);
  }
  100% {
    box-shadow: -3px -3px 10px var(--focus);
  }
`;

const UnlockCard = styled(Card)`
  animation: ${boxShadowAnimation} 4s infinite linear;
`;

const UnlockCardActions = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--smallPads);
`;

const UnlockCardText = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--smallPads);
`;

const UnlockCardSmall = styled.div``;

const UnlockCardSmallIcon = styled.div``;

const UnlockCardSmallImg = styled.div``;

const UnlockCardCover = styled.div`
  position: relative;
  width: 100%;
  height: ${(p) => (p.imgBehave == "Contain" ? "24rem" : "20rem")};
  padding: ${(p) => (p.imgBehave == "Contain" ? "2rem" : "0")};
  overflow: hidden;

  img {
    object-fit: ${(p) => (p.imgBehave == "Contain" ? "contain" : "cover")};
    width: 100%;
    height: 100%;
  }
`;

const UnlockCardLayer = styled.div`
  position: absolute;
  top: 0;
  left: 0;
  background: ${(p) => p.theme.high};
  z-index: 1;
  height: calc(100%);
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0.5;
  padding: 0.5rem;

  svg {
    fill: ${(p) => p.theme.low};
    max-width: 180px;
    width: 100%;
  }
`;

export const Unlock_Card = (props) => {
  return (
    <UnlockCard className={props.className} key={props.key}>
      {props.icon || props.header || props.imgSmall ? (
        <UnlockCardSmall>
          {props.icon ? (
            <UnlockCardSmallIcon>
              <IconSvg Icon={props.icon} />
            </UnlockCardSmallIcon>
          ) : (
            <UnlockCardSmallImg>
              <UnlockCardLayer></UnlockCardLayer>
              <img src={props.imgSmall} />
            </UnlockCardSmallImg>
          )}
        </UnlockCardSmall>
      ) : props.img ? (
        <UnlockCardCover imgBehave={props.imgBehave}>
          {/* <UnlockCardLayer>
            <IconSvg Icon="Lock" />
          </UnlockCardLayer> */}
          <img src={props.img} onLoad={props.onLoadImg} />
        </UnlockCardCover>
      ) : null}
      {props.title || props.subtitle ? (
        <UnlockCardText>
          {props.title && <h3>{props.title}</h3>}
          {props.subtitle && <h5>{props.subtitle}</h5>}
          {props.children}
        </UnlockCardText>
      ) : null}
      <UnlockCardActions>
        <Focus_
          className={props.className} 
          id={props.id}
          href={props.href}
          text={props.textBuy}
          iconRight={props.iconBuy}
          onClick={props.onBuy}
        />
      </UnlockCardActions>
    </UnlockCard>
  );
};
