import React from 'react'
import styled from 'styled-components'
import { Card } from '../../helpers/Card'
import { logo } from '../../styles/Theme'
import { useContext } from 'react'
import { ThemeContext } from '../../contexts'

const SubCard = styled.div`
    cursor: pointer;
`

const SubCardHeader = styled.div`
    display: flex;
    justify-content: center;
    padding: 1rem 1rem 2rem 1rem;
    img{
        width: 10rem;
        height: 10rem;
    }
`

const SubCardBody = styled.div`
    padding: 0 2rem 1rem 2rem;
    text-align: center;
    display: flex;
    justify-content: center;
    transform: translateX(-1rem);
    gap: 1rem;
`

const SubCardFooter = styled.div`
    padding: 1rem 2rem;
`

const SubCardBullet = styled.div`
    height: 1rem;
    width: 1rem;
    border-radius: 50%;
    background: ${p => p.active ? 'var(--success)' : 'var(--error)'};
`

export const Sub_Card = (props) => {

    const {theme} = useContext(ThemeContext);

  return (
    <SubCard key={props.key} id={props.id} onClick={props.onClick}>
        <SubCardHeader>
            {props.lois ?
                <img src={logo.lois[theme]} />
            :props.dailyprofit ?
                <img src={logo.dailyprofit[theme]} />
            :
                <img src={logo.bond[theme]} />
            }
        </SubCardHeader>
        <SubCardBody>
            {props.active ?
                <SubCardBullet active></SubCardBullet>
            :
                <SubCardBullet></SubCardBullet>
            }
            {props.lois ?
                <h3>Adsnap</h3>
            :props.dailyprofit ?
                <h3>Questad</h3>
            :
                <h3>Tailormade</h3>
            }
        </SubCardBody>
        {props.children}
    </SubCard>
  )
}
