import React, { useContext } from "react";
import { RegionContext } from "../../contexts/LocalContext";
import { MenuContext } from "../../contexts/NavbarContext";
import { Ham, HamItem, HamTitle } from "../../styles/Ham";
import { IconSvg } from "../../svg/IconSvg";
import { countries } from "../../json/countries.js";

export const Nav_Ham_Region = (props) => {
  const { region, setRegion } = useContext(RegionContext);
  const { setActiveMenu } = useContext(MenuContext);
  const updateRegion = (selectedRegion) => {
    setRegion(selectedRegion);
    setActiveMenu("Main");
  };

  return (
    <Ham>
      <HamTitle onClick={() => setActiveMenu("Main")}>
        <IconSvg Icon="Back" />
        <h4>{props.text_Title_Region}</h4>
      </HamTitle>
      {countries
        ?.sort((a, b) => a.country.localeCompare(b.country))
        ?.map((country, i) => (
          <HamItem
            key={i}
            onClick={() => updateRegion(country.country)}
            className={region === country.country ? "SelectedRegion" : ""}
          >
            <main>
              <h5>{country.country}</h5>
            </main>
          </HamItem>
        ))}
    </Ham>
  );
};
