import React from "react";
import styled from "styled-components";
import { IconSvg } from "../../svg/IconSvg";
import { Input_ } from "./Input_";

const Checkbox = styled.div`
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: flex-start;
  grid-gap: 1rem;
  user-select: none;
  width: 100%;
  margin-top: 1rem;

  &:first-of-type {
    margin-top: 0;
  }

  label {
    cursor: pointer;

    &:hover ~ .Check {
      background: ${(props) => props.theme.low};
    }
  }

  .CheckInput {
    opacity: 0.3;
    cursor: not-allowed;
    pointer-events: none;
  }
`;

const Check = styled.div`
  position: relative;
  height: 2rem;
  width: 2rem;
  background: ${(props) => props.theme.background};
  box-shadow: ${(props) => props.theme.in};
  border: 1px solid ${p => p.theme.mid};
  border-radius: 0.5rem;
  grid-column-start: 1;
  grid-column-end: 2;
  grid-row-start: 1;
  grid-row-end: 2;

  .CheckCustom {
    position: absolute;
    top: 0;
    left: 0;
    height: 100%;
    width: 100%;
    pointer-events: none;
  }

  svg {
    fill: var(--white);
    opacity: 0;
    transition: opacity 0.2s ease-in-out;
    position: absolute;
    top: 0;
    left: 0;
    height: 100%;
    width: 100%;
    padding: 0.3rem;
  }

  input {
    opacity: 0;
    z-index: 15;
    position: absolute;
    cursor: pointer;
    top: 0;
    left: 0;
    height: 100%;
    width: 100%;

    &:checked ~ .CheckCustom {
      background: var(--main);
      border-radius: 0.5rem;
      box-shadow: inset 1px 1px 2px var(--mainDark),
        inset -1px -1px 2px var(--mainLight);
    }

    &:checked ~ .CheckIcon {
      opacity: 1 !important;
    }
  }
`;

const CheckboxInput = styled.div`
  input {
    opacity: ${(p) => (p.disabled === true ? "1" : "0.4")};
    cursor: ${(p) => (p.disabled === true ? "auto" : "not-allowed !important")};
  }
`;

export const Checkbox_ = (props) => {
  return (
    <Checkbox
      className={props.className + " " + "Checkbox"}
      id={props.id}
      key={props.key}
      onClick={props.onClick}
    >
      {props.withInput ? (
        <CheckboxInput disabled={props.disable}>
          <Input_
            placeholder={props.placeholder}
            disabled={props.disable}
            checked={props.checked}
            value={props.value}
          />
        </CheckboxInput>
      ) : (
        <label for={props.id}>
          <p>{props.text}</p>
        </label>
      )}
      <Check className="Check">
        <input
          type="checkbox"
          id={props.id}
          onChange={props.onChange}
          checked={props.checked}
          value={props.value}
          name={props.name}
        />
        <span className="CheckCustom"></span>
        <IconSvg Icon="Check" class_Icon="CheckIcon" />
      </Check>
    </Checkbox>
  );
};
