import React from "react";
import styled from "styled-components";
import Upload_ from "./Upload_";
import {
  ValidatorError,
  ValidatorSuccess,
  ValidatorTip,
  ValidatorWarning,
  Validators,
} from "../../helpers/Validator";
import { Red_ } from "../button";
import { IconSvg } from "../../svg/IconSvg";


const UploadMedia = styled.div`

  h4 {
    margin-bottom: 2rem;
  }
`;

const UploadMediaGrid = styled.div``;

const UploadMediaFile = styled.div`
    padding-left: 1rem;
`;

const UploadMediaActions = styled.div`
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-top: 1rem;
`;

export const Upload_Media = (props) => {
  return (
    <UploadMedia>
      <h4>{props.title}</h4>
      <UploadMediaGrid className="UploadMediaGrid">
        <UploadMediaFile>
          {props.uploaded ? 
            <p>{props.filename}</p>
           : null}
        </UploadMediaFile>
        <UploadMediaActions>
          <Upload_
            maxFiles="1"
            getFilesFromChild={props.getFilesFromChild}
            boomRejected={props.boomRejected}
            accept={props.accept}
            onClick={props.onUpload}
            text={props.upload}
            iconLeft={props.iconUpload ? props.iconUpload : "Upload"}
            maxSize={props.maxSize}
            userId={props.userId}
            type = 'media'
          />
          {props.uploaded ? (
            <Red_
              onClick={props.onDelete}
              text={props.delete}
              iconLeft={props.iconUpload ? props.iconUpload : "Delete"}
            />
          ) : null}
        </UploadMediaActions>
        {props.errors ? (
          <Validators className="ValidatorErrors">
            {props.errors?.map((error, i) => (
              <ValidatorError key={i}>
                <IconSvg Icon="Error" />
                <h6>{error}</h6>
              </ValidatorError>
            ))}
          </Validators>
        ) : null}
        {props.successes ? (
          <Validators className="ValidatorSuccesses">
            {props.successes?.map((success, i) => (
              <ValidatorSuccess key={i}>
                <IconSvg Icon="Check" />
                <h6>{success}</h6>
              </ValidatorSuccess>
            ))}
          </Validators>
        ) : null}
        {props.helpers ? (
          <Validators className="ValidatorHelpers">
            {props.helpers?.map((helper, i) => (
              <ValidatorWarning key={i}>
                <IconSvg Icon="Warning" />
                <h6>{helper}</h6>
              </ValidatorWarning>
            ))}
          </Validators>
        ) : null}
        {props.tips ? (
          <Validators className="ValidatorTips">
            {props.tips?.map((tip, i) => (
              <ValidatorTip key={i}>
                <IconSvg Icon="Tip" />
                <h6>{tip}</h6>
              </ValidatorTip>
            ))}
          </Validators>
        ) : null}
      </UploadMediaGrid>
    </UploadMedia>
  );
};
