import React from 'react'
import styled, { keyframes } from 'styled-components'

const Fade = keyframes`
    0% { 
        opacity: 1;
    }
    20% { 
        opacity: 0.5;
    }
    90%{
        opacity: 0.8;
    }
    100% { 
        opacity: 1;
    }
`

const Slide = keyframes`
    0%{
        transform: translate(-100%);
    }
    100% { 
        transform: translate(100%);
    }
`

const CardLoader = styled.div`
    width: 100%;
    background: ${p => p.theme.mid};
    height: 30rem;
    border-radius: var(--normalRadius);
    overflow: hidden;
    animation: ${Fade} infinite 2s ease-in-out;
`

const CardSlider = styled.div`
    animation: ${Slide} infinite 2s ease-in-out;
    height: 100%;
    width: 100%;
    position: absolute;
    top: 0;
    left: 0;
    background: linear-gradient(to right, transparent, ${p => p.theme.high});
`

const CardLoaderImg = styled.div`
    position: relative;
    height: 20rem;
    background-color: ${p => p.theme.low};
    display: flex;
    align-items: center;
    overflow: hidden;
    justify-content: center;
`

const CardLoaderCircle = styled.div`
    width: 10rem;
    height: 10rem;
    border-radius: 50%;
    background-color: ${p => p.theme.mid};
    position: relative;
`

const CardLoaderTitle = styled.div`
    width: 80%;
    height: 2rem;
    border-radius: 4rem;
    background-color: ${p => p.theme.low};
    margin: 2rem auto;
    overflow: hidden;
    position: relative;
`

export const Card_Loader = (props) => {
  return (
    <CardLoader key={props.key}>
        <CardLoaderImg>
            <CardSlider/>
            {props.circle && 
                <CardLoaderCircle></CardLoaderCircle>
            } 
        </CardLoaderImg>
        <CardLoaderTitle>
            <CardSlider></CardSlider>
        </CardLoaderTitle>
        {props.children}
    </CardLoader>
  )
}
