import React from "react";
import {
  ValidatorError,
  ValidatorRequired,
  Validators,
  ValidatorSuccess,
  ValidatorTip,
  ValidatorWarning,
} from "../../helpers/Validator";
import { FormGroup, FormInput, FormLabel, FormList } from "../../styles/Form";
import { IconSvg } from "../../svg/IconSvg";
import { Delete_Plain, Main_ } from "../button";

export const Input_ = (props) => {
  return (
    <FormGroup className="FormGroup">
      <FormInput
        value={props.value}
        className={props.className + " " + "FormInput"}
        placeholder={props.placeholder}
        id={props.id}
        autoComplete={props.autoComplete ? props.autoComplete : "off"}
        type={props.type ? props.type : "text"}
        name={props.name}
        onChange={props.onChange}
        defaultValue={props.defaultValue}
        onKeyPress={props.onKeyPress}
        onKeyDown={props.onKeyDown}
        disabled={props.disabled}
        ref={props.ref}
        onBlur={props.onBlur}
        inputMode={props.inputMode}
        onWheel={props.onWheel}
      />
      <FormLabel className="FormLabel">{props.placeholder}</FormLabel>
      {props?.list ? (
        <Main_
          size="small"
          text={props.add}
          iconLeft="Add"
          className="FormAddButton"
          onClick={props.onAdd}
        />
      ) : null}
      {props.required ? (
        <ValidatorRequired className="ValidatorRequired">
          <IconSvg Icon="Asterisk" />
        </ValidatorRequired>
      ) : null}
      {props.errors?.length ? (
        <Validators className="ValidatorErrors">
          {props.errors?.map((error, i) => (
            <ValidatorError key={i}>
              <IconSvg Icon="Error" />
              <h6>{error}</h6>
            </ValidatorError>
          ))}
        </Validators>
      ) : null}
      {props.successes?.length ? (
        <Validators className="ValidatorSuccesses">
          {props.successes?.map((success, i) => (
            <ValidatorSuccess key={i}>
              <IconSvg Icon="Check" />
              <h6>{success}</h6>
            </ValidatorSuccess>
          ))}
        </Validators>
      ) : null}
      {props.helpers?.length ? (
        <Validators className="ValidatorHelpers">
          {props.helpers?.map((helper, i) => (
            <ValidatorWarning key={i}>
              <IconSvg Icon="Warning" />
              <h6>{helper}</h6>
            </ValidatorWarning>
          ))}
        </Validators>
      ) : null}
      {props.tips ? (
        <Validators className="ValidatorTips">
          {props.tips?.map((tip, i) => (
            <ValidatorTip key={i}>
              <IconSvg Icon="Tip" />
              <h6>{tip}</h6>
            </ValidatorTip>
          ))}
        </Validators>
      ) : null}
      {props.list?.length ? (
        <FormList className="FormList">
          {props.defaultListItem ? (
            <li>
              <IconSvg Icon={props.icon_ListItem} />
              <h6>{props.defaultListItem}</h6>
              {props.deleteDefaultListItem ? (
                <Delete_Plain
                  onClick={props.onDeleteDefault}
                  size="small"
                  iconLeft="Delete"
                />
              ) : null}
            </li>
          ) : null}
          {props.list?.map((item, i) => (
            <li key={i}>
              <IconSvg Icon={props.icon_ListItem} />
              <div>
                <h6>{item}</h6>
                {props.childrenItem}
              </div>
              <Delete_Plain
                onClick={() => props.onDelete(i)}
                size="small"
                iconLeft="Delete"
              />
            </li>
          ))}
        </FormList>
      ) : null}
    </FormGroup>
  );
};
