import React, { useEffect, useState } from "react";
import styled from "styled-components";
import { breakPoints } from "../../helpers/MediaQ";
import { CardsForty } from "../../styles/Cards";
import { Card_Loader } from "./Card_Loader";

const FortyCardLoader = styled(CardsForty)``;

export const Forty_Card_Loader = (props) => {
  // Function to calculate repeats based on width and return the value
  const getInitialRepeats = () => {
    const width = window.innerWidth;
    if (width > breakPoints.xl) {
      return 4;
    } else if (width <= breakPoints.xl && width > breakPoints.md) {
      return 2;
    }
    return 2; // Default value if no conditions match
  };

  const [repeats, setRepeats] = useState(getInitialRepeats);

  // Function to update repeats based on width
  const changeRepeats = (width) => {
    if (width > breakPoints.xl) {
      setRepeats(4);
    } else if (width <= breakPoints.xl && width > breakPoints.md) {
      setRepeats(2);
    }
  };

  // Use useEffect to handle resize events and initial load
  useEffect(() => {
    // Set initial repeats on mount (redundant here since useState already does it, but keeping for clarity)
    changeRepeats(window.innerWidth);

    // Add resize event listener
    const handleResize = () => {
      changeRepeats(window.innerWidth);
    };
    window.addEventListener('resize', handleResize);

    // Cleanup listener on unmount
    return () => {
      window.removeEventListener('resize', handleResize);
    };
  }, []); // Empty dependency array means this runs once on mount

  return (
    <FortyCardLoader>
      {[...Array(repeats)]?.map((_, i) => (
        <Card_Loader key={i} children={props.children} circle={props.circle} />
      ))}
    </FortyCardLoader>
  );
};
