import styled from "styled-components";
import { Input, Label } from "../helpers/Input";

export const Form = styled.div`
  padding: ${(p) => (p.noPads ? "0" : "var(--smallDist)")};
  background: ${(p) => p.theme.low};
  border-radius: var(--normalRadius);

  h3 {
    margin-bottom: 4rem;
  }
`;

export const FormBoxTitle = styled.div`
  display: flex;
  align-items: center;
  margin-bottom: 1rem;
`

export const FormBox = styled.div`
    background: ${p => p.theme.low};
    border: 2px solid ${p => p.theme.mid};
    border-radius: var(--smallRadius);
    padding: var(--normalPads);
    margin-bottom: 2rem;
    cursor: ${p => p.filled ? "pointer" : "normal"};
    transition: box-shadow .5s;
    pointer-events: ${p => p.noEvents ? "none" : "normal"};
    box-shadow: ${p => p.theme.out};

    &:hover{
        box-shadow: ${p => p.filled ? p.theme.outFocus : p.theme.out};
        transition: box-shadow .5s;
    }

    .FilledEdit{
        display: flex;
        align-items: center;
        width: 3rem;
        max-width: 0;
        overflow: hidden;
        transition: max-width .5s;

        svg{
            width: var(--largeIcon);
            fill: var(--main);
        }
    }

    &:hover .FilledEdit{
        max-width: 3rem;
        transition: max-width .5s;
    }
`

export const FormBoxAction = styled.div`
    display: flex;
    justify-content: flex-end;
    margin-top: 2rem;
`

export const FormBoxSelection = styled.div`
    background: ${p => p.theme.mid};
    border-radius: var(--smallRadius);
    padding: var(--normalPads);
`

export const FormInput = styled(Input)`
  padding-top: 3rem;
`;

export const FormLabel = styled(Label)`
  font-size: var(--smallText);
  color: var(--greyDark);
`;

export const FormGroup = styled.div`
  position: relative;

  label {
    position: absolute;
    top: 1.8rem;
    left: 1.6rem;
    transform: translateY(-1rem);
    visibility: visible;
    opacity: 1;
    transition-property: opacity, transform;
    transition-duration: 0.5s;
  }

  .FormAddButton {
    display: flex;
    position: absolute;
    top: 1.5rem;
    right: 1.6rem;
  }

  .ValidatorTips {
    /* display: none; Tips are shown only on focus */
    display: block;
  }

  .ValidatorErrors {
    display: none;
  }

  input:focus {
    & ~ .ValidatorTips {
      display: block;
    }

    & ~ .ValidatorRequired {
      display: none;
    }
  }

  input:placeholder-shown {
    ~ label {
      transform: translateY(0rem);
      visibility: hidden;
      opacity: 0;
    }

    ~ .ValidatorHelpers {
      display: none;
    }

    ~ .ValidatorErrors {
      display: block;
    }

    ~ .FormAddButton {
      display: none;
    }
  }
`;

export const FormList = styled.ul`
  margin-top: 2rem;

  li {
    display: grid;
    grid-template-columns: auto 1fr auto;
    align-items: center;
    grid-gap: 1rem;
    padding: 0.5rem 1.6rem;

    svg {
      width: var(--smallIcon);
      fill: ${(p) => p.theme.color};
    }
  }
`;
