import React from 'react'
import styled from 'styled-components'
import { Main_ } from '../button/Main_'

const Filters = styled.div`
    position: sticky;
    top: 7rem;
    z-index: 10;
    margin-bottom: 2rem;
    padding: .5rem;
    background: ${p => p.theme.low};
    border-radius: var(--smallRadius);
`

const FIltersContainer = styled.div`
    position: relative;
    display: flex;
    justify-content: flex-end;
    align-items: center;
    gap: 1rem;
`

const FiltersButton = styled.div``

const FiltersSearch = styled.div`
    width: 100%;
`

export const Filters_ = (props) => {
  return (
    <Filters className='Filters'>
        <FIltersContainer>
            {props.children}
            {props.filters ?
                <FiltersButton>
                    <Main_ size="small" text={props.filters} onClick={props.onFilters} iconRight="Filter"/>
                </FiltersButton>
            :
                null
            }
            {props.search ?
                <FiltersSearch>
                    {props.search}
                </FiltersSearch>
            :
                null
            }
        </FIltersContainer>
    </Filters>
  )
}



