import React, { useState } from "react";
import styled from "styled-components";
import { Card } from "../../helpers/Card";
import { device } from "../../helpers/MediaQ";

const PresetCard = styled(Card)`
  cursor: pointer;
  box-shadow: ${(p) => (p.selected ? p.theme.inFocus : p.theme.out)};

  &:hover {
    box-shadow: ${(p) => (p.selected ? p.theme.inFocus : p.theme.outFocus)};
    transition: box-shadow 0.5s;
  }
`;

const PresetHeader = styled.div`
  height: 20rem;
  margin: ${(p) => (p.selected ? "6px auto 0 auto" : "inherit")};
  width: ${(p) => (p.selected ? "calc(100% - 6px)" : "100%")};
  background: ${(p) => (p.selected ? p.theme.background : p.theme.low)};
`;

const CardSvg = styled.div`
  background: ${(p) => p.theme.background};
  border-radius: 50%;
  padding: 3rem;

  svg {
    width: 5rem;
    fill: ${(p) => p.theme.mid};
  }
`;

const CardImageSmall = styled.div`
  img {
    object-fit: cover;
    height: 11rem;
    width: 11rem;
    border-radius: 50%;
  }
`;

const PresetList = styled.ul`
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
  padding: 1rem;
`;

const PresetItem = styled.li`
  padding: 0.5rem 1rem;
  width: calc(50% - 0.5rem);
  background: ${(p) => (p.selected ? p.theme.low : p.theme.background)};
  border-radius: 0.5rem;
  white-space: nowrap;
  overflow: hidden;

  h5 {
    color: ${(p) => (p.selected ? "var(--main)" : "inherit")};
  }
`;

const CardBottom = styled.div`
  padding: var(--normalPads);

  h3,
  h5 {
    text-align: center;
    white-space: nowrap;
    width: calc(100%);
    overflow: hidden;
  }
`;

const CardTitle = styled.div`
  h3,
  h5 {
    text-align: center;
  }
`;

const CardFix = styled.div`
  position: relative;
`;

const CardFixText = styled.h6`
  position: absolute;
  top: 50%;
  left: 50%;
  height: 3rem;
  width: 100%;
  transform: translate(-50%, -50%);
  z-index: 2;
  padding: 0.5rem 1rem;
  background: ${(p) => p.theme.low};
  border-radius: var(--smallRadius);
  text-align: center;

  @media ${device.sm} {
    display: none;
  }
`;

export const Preset_Card = (props) => {
  const maxTitle = 16;
  const maxSubtitle = 30;
  const maxItem = 20;
  const [nameIsHovered, setNameIsHovered] = useState(false);

  return (
    <PresetCard
      selected={props.selected}
      onClick={props.onClick}
      id={props.id}
      href={props.href}
    >
      <PresetHeader selected={props.selected}>
        {props.items ? (
          <PresetList>
            {props?.items.slice(0, 9).map((item, i) => (
              <PresetItem selected={props.selected} key={i}>
                {props.isJson ? (
                  <h5>{item[props.itemKey]}</h5>
                ) : (
                  <h5>{item}</h5>
                )}
              </PresetItem>
            ))}
            {props.items?.length >= 10 ? (
              <PresetItem selected={props.selected}>
                <h5>...</h5>
              </PresetItem>
            ) : null}
          </PresetList>
        ) : null}
      </PresetHeader>
      {props.title || props.subtitle ? (
        <CardBottom
          onMouseEnter={() => setNameIsHovered(true)}
          onMouseLeave={() => setNameIsHovered(false)}
        >
          {props.title && (
            <CardTitle>
              {props.title?.length <= maxTitle ? (
                <h3>{props.title}</h3>
              ) : (
                <CardFix>
                  <h3>{props.title.substring(0, maxTitle) + "..."}</h3>
                  {nameIsHovered && <CardFixText>{props.title}</CardFixText>}
                </CardFix>
              )}
            </CardTitle>
          )}
          {props.subtitle && (
            <CardTitle>
              {props.subtitle?.length <= maxSubtitle ? (
                <h5>{props.subtitle}</h5>
              ) : (
                <CardFix>
                  <h5>{props.subtitle.substring(0, maxSubtitle) + "..."}</h5>
                  {nameIsHovered && <CardFixText>{props.subtitle}</CardFixText>}
                </CardFix>
              )}
            </CardTitle>
          )}
        </CardBottom>
      ) : null}
    </PresetCard>
  );
};
