import React from "react";
import styled from "styled-components";
import { Main_Plain } from "../button";
import { IconSvg } from "../../svg/IconSvg";

const SectionTitle = styled.div`
  margin: 2rem 0;
  display: ${(p) => (p.onEdit ? "flex" : "block")};
  align-items: center;
`;

const SectionWrapper = styled.div`
  background: ${(p) => p.theme.mid};
  padding: var(--normalPads);
  border-radius: var(--smallRadius);
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
`;

const SectionTitleLeft = styled.div`
  display: flex;
  align-items: center;
  gap: 1rem;
  img {
    height: 1.8rem;
  }
  svg {
    width: 1.8rem;
  }
`;

const SectionTitleText = styled.h4``;

const SectionTitleValue = styled.h4``;

export const Section_Title = (props) => {
  return (
    <SectionTitle onEdit={props.onEdit}>
      <SectionWrapper>
        <SectionTitleLeft>
          {props.icon ? (
            <IconSvg Icon={props.icon} />
          ) : props.img ? (
            <img src={props.img} />
          ) : null}
          <SectionTitleText>{props.text}</SectionTitleText>
        </SectionTitleLeft>

        <SectionTitleValue>{props.value}</SectionTitleValue>
      </SectionWrapper>
      {props.onEdit ? (
        <Main_Plain iconLeft="Edit" onClick={props.onEdit} />
      ) : null}
    </SectionTitle>
  );
};
