import React, { useContext } from "react";
import styled from "styled-components";
import { ThemeContext } from "../../contexts";
import { device } from "../../helpers/MediaQ";

const NavLogo = styled.div`
  display: flex;
  gap: 1rem;
  align-items: flex-start;
  cursor: pointer;
  width: 30rem;
  border-right: 2px solid ${p => p.theme.low};
  padding: 1rem 4rem;

  img {
    height: 4rem;
    transition-property: transform;
    transition-duration: 0.5s;
  }

  &:hover {
    img {
      transform: rotate(25deg);
    }
  }

  &:active {
    img {
      transform: rotate(55deg);
    }
  }

  @media ${device.sm} {
    padding: 1.25rem 2rem;
    width: auto;

    img{
      height: 3.5rem;
    }
  }
`;

const NavText = styled.div`

  h2{
    line-height: 1;
    margin-bottom: 5px;
  }

  h6 {
    color: var(--focus) !important;
    font-size: 1.2rem;
    font-family: "fontMedium", sans-serif;
    line-height: 0.5;
    margin-left: 0.2rem;
    font-weight: 600;
  }

  @media ${device.sm} {
    display: none;

    h6 {
      span {
        display: none;
      }
    }
  }

  @media ${device.xs} {
    width: auto;

    h2{
      display: none;
    }

  }
`;

export const Nav_Logo = (props) => {
  const { theme } = useContext(ThemeContext);

  return (
    <NavLogo onClick={props.onClick_Logo}>
      {theme === "dark" ? (
        <img
          alt="Doitforme dark logo"
          src="https://genius1071.friktoriaservers.net/doitforme/logo/logo_dark.svg"
        />
      ) : (
        <img
          alt="Doitforme light logo"
          src="https://genius1071.friktoriaservers.net/doitforme/logo/logo_light.svg"
        />
      )}
      <NavText>
        <h2>Doitforme</h2>
        <h6>
          v4.{props.majorV}.{props.minorV} <span>'Miracle'</span>
        </h6>
      </NavText>
    </NavLogo>
  );
};
