import React from "react";
import styled from "styled-components";
import { IconSvg } from "../../svg/IconSvg";
import { Button } from "../../helpers/Button";

const Black = styled(Button)`
  background: ${(p) => p.theme.color};
  border-radius: var(--normalRadius);
  border: 1px solid ${(p) => p.theme.color};

  span {
    color: ${(p) => p.theme.background};
  }

  svg {
    fill: ${(p) => p.theme.background};
  }

  &:hover {
    background: ${(p) => p.theme.high};
    border: 1px solid ${(p) => p.theme.high};
  }
`;

export const Black_ = (props) => {
  return (
    <Black
      className={props.className + " " + "Black"}
      id={props.id}
      size={props.size}
      onClick={props.onClick}
    >
      {props.iconLeft ? (
        <IconSvg Icon={props.iconLeft} />
      ) : props.localIconLeft ? (
        <>{props.localIconLeft}</>
      ) : null}
      {props.text ? <span>{props.text}</span> : null}
      {props.iconRight ? (
        <IconSvg Icon={props.iconRight} />
      ) : props.localIconRight ? (
        <>{props.localIconRight}</>
      ) : null}
    </Black>
  );
};
