import React from 'react'
import styled, { keyframes } from 'styled-components'
import { device } from '../../helpers/MediaQ'
import { Main_ } from '../button/Main_'
import { Main_Plain } from '../button/Main_Plain'
import { Grey_Link } from '../button/Grey_Link'

const SlideIn = keyframes`
 0%{
    top: -100%;
 }
 100%{
    top: 5rem;
 }
`

const Notify = styled.div`
    position: ${p => p.storybook ? 'static' : 'fixed'};
    top: 0;
    left: 0;
    z-index: 5000;
    width: 100%;
    min-height: 100vh;
    background: ${p => p.theme.overlay};
`

const NotifyTop = styled.div`
    display: flex;
    align-items: center;
    justify-content: flex-end;
    margin-bottom: 1rem;
`

const NotifyBackground = styled.div`
    position: ${p => p.storybook ? 'static' : 'fixed'};
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    z-index: 4999;
`

const NotifyContainer = styled.div`
    position: ${p => p.storybook ? 'static' : 'fixed'};
    top: 5rem;
    left: 50%;
    width: calc(100vw - 4rem);
    max-width: 50rem;
    transform: translateX(-50%);
    z-index: 5001;
    padding: var(--normalPads);
    border-radius: var(--smallRadius);
    background: ${p => p.theme.background};
    text-align: center;
    animation: ${SlideIn} .5s linear;
`

const NotifyActions = styled.div`
    margin-top: 2rem;
    padding: 1rem 0;
    display: flex;
    align-items: center;
    justify-content: space-between;

    @media ${device.sm}{
        
        button{

            span{
                display: none;
            }
        }
    }
`

export const Notify_ = (props) => {
    return (
      <Notify storybook={props.storybook} className={props.className + ' ' + 'Notify'} >
          <NotifyBackground onClick={props.onBackground}></NotifyBackground>
          <NotifyContainer storybook={props.storybook}>
            {props.onClose ?
                <NotifyTop>
                    <Grey_Link noPadding iconLeft="Xicon" onClick={props.onClose}/>
                </NotifyTop>
            :
                null
            }
              {props.children}
            {props.actions ?
              <NotifyActions>
                  <Main_Plain 
                    id={props.idYes}
                    onClick = {props.onYes}
                    iconLeft = 'Check'
                    text = {props.yes}
                  />
                  <Main_ 
                    id={props.idNo}
                    onClick = {props.onNo}
                    iconLeft = 'Xicon'
                    text = {props.no}
                  />
              </NotifyActions>
            : 
                null 
            }
          </NotifyContainer>
      </Notify>
    )
  }
