import React from "react";
import { CSSTransition } from "react-transition-group";
import styled from "styled-components";
import { Steps_Actions } from "./Steps_Actions";
import { Steps_Header } from "./Steps_Header";

const Steps = styled.div``;

const StepsContainer = styled.div`
  position: relative;

  .Steps {
    width: 100%;
  }

  .Steps-enter {
    position: absolute;
    transform: translateX(-110%);
  }

  .Steps-enter-active {
    transform: translateX(0%);
    transition: all 0.5s ease;
  }

  .Steps-exit {
    position: absolute;
  }

  .Steps-exit-active {
    transform: translateX(-110%);
    transition: all 0.4s ease;
  }
`;

const StepsWrapper = styled.div`
  padding: var(--smallDist);
  border-radius: var(--normalRadius);
  box-shadow: ${(p) => p.theme.out};
  background: ${(p) => p.theme.low};

  h3 {
    margin-bottom: 2rem;
  }
`;

export const Steps_ = (props) => {
  return (
    <Steps className={props.className + " " + "Steps"}>
      <Steps_Header steps={props.steps} currentStep={props.currentStep} />
      <StepsContainer className="StepsContainer">
        {props.steps?.map((step, i) => (
          <CSSTransition
            in={props.currentStep === i}
            timeout={500}
            unmountOnExit
            classNames="Steps"
          >
            <StepsWrapper className="Steps">{step}</StepsWrapper>
          </CSSTransition>
        ))}
      </StepsContainer>
    </Steps>
  );
};
