import React from 'react'
import styled from 'styled-components'
import { PageAlwaysVisible, PageForty, PageIllu, PageTitle } from '../../styles/Page'
import { Actions_, Grey_, Main_ } from '../button'

const Single = styled(PageForty)`
    width: 100%;
`

const SingleText = styled.div`

    h2{
        color: var(--greyDark) !important;
        font-size: 4rem;
    }
    
    h3{
        margin-bottom: 4rem;
        color: var(--greyDark) !important;
    }
`

export const Single_ = (props) => {
  return (
    <Single >
        <PageAlwaysVisible>
            <PageTitle>
                <h1>{props.title}</h1>
            </PageTitle>
            <SingleText>
                <h2>{props.subtitle}</h2>
                <h3>{props.text}</h3>
                {props.textMain || props.textGrey ?
                    <Actions_>
                        {props.textGrey ?
                            <Grey_
                                className={props.className} 
                                id={props.id}
                                text = {props.textGrey}
                                noPadding
                                onClick = {props.onClickGrey}
                                iconLeft = {props.iconGrey}
                            />
                        :
                            null
                        }
                        {props.textMain ?
                            <Main_ 
                                className={props.className} 
                                id={props.id}   
                                text = {props.textMain}
                                noPadding
                                onClick = {props.onClickMain}
                                iconRight = {props.iconMain}
                            />
                        :
                            null
                        }
                    </Actions_>
                :
                    null
                }
            </SingleText>
        </PageAlwaysVisible>
        <PageAlwaysVisible>
            <PageIllu>
                <img src={props.backgroundImage} alt={props.backgroundAlt}/>
            </PageIllu>
        </PageAlwaysVisible>
    </Single>
  )
}
