import React, { useEffect, useState } from "react";
import styled from "styled-components";
import Fuse from "fuse.js";
import _ from "lodash";
import greekUtils from "greek-utils"
import { FormGroup, FormInput, FormLabel } from "../../styles/Form.js";
import { IconSvg } from "../../svg/IconSvg.js";

const GoogleSearch = styled.div``;

const GoogleForm = styled(FormGroup)``;

const GoogleInput = styled(FormInput)`
  padding-left: 4.5rem;
`;

const GoogleLabel = styled(FormLabel)`
  padding-left: 3rem;
`;

const GoogleSearchIcon = styled.div`
  position: absolute;
  top: 1.5rem;
  left: 1rem;

  svg {
    width: 3rem;
    fill: var(--greyDark);
  }
`;

export const Google_Search = (props) => {
  let fuseOptions = {
    includeScore: true,
    keys: props.fileKeys,
    isCaseSensitive: props?.isCaseSensitive ? true : false,
  };

  const [file, setFile] = useState([]);

  const [currentSearch, setCurrentSearch] = useState({
    query: "",
    file,
    notfoundmessage: false,
    defaultValue: props.defaultValue,
  });

  const constructQuery = (e) => {
    let query = e.target.value;

    if (props.sanitize) query = greekUtils.toGreeklish(query);

    query = query.split(" ");
    query = query.filter((element) => element !== "");
    query = query.join(" ");

    if (
      props.applyReverseFileProperties &&
      props.applyReverseFileProperties?.length > 0
    ) {
      for (let property of props.applyReverseFileProperties) {
        for (let item of file) {
          if (item[property?.originalKey])
            item[property?.reversedKey] = item[property?.originalKey]
              .split(" ")
              .reverse()
              .join(" ");
        }
      }
    }

    if (props.minMatchCharacters) {
      if (query?.length < props.minMatchCharacters) {
        setCurrentSearch({ ...currentSearch, query: query });
        props.setResults([]);
        if (props?.setInputSize) props.setInputSize(query?.length);
        return;
      }
    }

    if (props.maxMatchCharacters) {
      if (query?.length > props.maxMatchCharacters) {
        setCurrentSearch({ ...currentSearch, query: query });
        props.setResults([]);
        if (props?.setInputSize) props.setInputSize(query?.length);
        return;
      }
    }

    if (query != currentSearch?.query)
      setCurrentSearch({ ...currentSearch, query: query });
  };

  const debounce = (func, wait) => {
    let timeout;
    return (...args) => {
      clearTimeout(timeout);
      timeout = setTimeout(() => {
        func(...args);
      }, wait);
    };
  };

  const triggerDebounce = props?.debounceTime
    ? debounce(constructQuery, props.debounceTime)
    : constructQuery;

  const executeSearch = () => {
    const fuse = new Fuse(file, fuseOptions);

    let suggestions = currentSearch.query
      ? fuse.search(currentSearch.query)
      : file;

    if (props.maxAcceptedScore) {
      let newSuggestions = [];
      for (let suggestion of suggestions) {
        if (suggestion?.score < props?.maxAcceptedScore)
          newSuggestions.push(suggestion);
      }
      suggestions = newSuggestions;
    }

    suggestions = suggestions?.map((item) => {
      return item?.item;
    });

    if (
      props?.applyReverseFileProperties &&
      props?.applyReverseFileProperties?.length > 0
    ) {
      for (let property of props.applyReverseFileProperties) {
        for (let item of suggestions) {
          if (item[property?.reversedKey]) delete item[property?.reversedKey];
        }
      }
    }

    props.setResults(
      currentSearch.query?.length
        ? { data: suggestions, input: currentSearch.query }
        : { data: [], input: "" }
    );
  };

  useEffect(() => {
    if (currentSearch?.query) executeSearch();
    else props.setResults({ data: [], input: "" });
  }, [currentSearch]);

  useEffect(() => {
    setFile(props.file);
  }, [props.file]);

  return (
    <GoogleSearch>
      <GoogleForm>
        <GoogleInput
          placeholder={props.placeholder}
          onChange={triggerDebounce}
          defaultValue={currentSearch.defaultValue}
          disabled={props.disabled}
        />
        <GoogleLabel>{props.placeholder}</GoogleLabel>
        <GoogleSearchIcon>
          <IconSvg Icon="Search" />
        </GoogleSearchIcon>
      </GoogleForm>
    </GoogleSearch>
  );
};
