import React from "react";
import styled from "styled-components";
import { device } from "../../helpers/MediaQ";

const Builder = styled.div`
  margin-bottom: ${(p) => (p.last ? "0" : "2rem")};
  display: ${(p) => (p.split ? "grid" : "block")};
  grid-column-gap: 2rem;

  h4 {
    padding-bottom: 1rem;
    grid-column-start: 1;
    grid-column-end: 3;
  }

  @media ${device.sm} {
    display: ${(p) => (p.split ? "grid" : "block")};
    grid-template-columns: 1fr;
  }
`;

export const Builder_ = (props) => {
  return (
    <Builder
      className={props.className + " " + "Builder"}
      split={props.split}
      last={props.last}
      key={props.key}
    >
      {props.title ? <h4>{props.title}</h4> : null}
      {props.children}
    </Builder>
  );
};
